python3 -c "import re,subprocess,sys; src=open('src/lib.rs').read(); attr=re.search(r'migrations_max_lamports\s*=\s*([0-9_]+|[A-Za-z_][A-Za-z0-9_]*)', src); value=None
if attr:
    token=attr.group(1)
    if token[0].isdigit(): value=int(token.replace('_',''))
    else:
        c=re.search(r'const\s+'+re.escape(token)+r'\s*:\s*u64\s*=\s*([0-9_]+)', src)
        if c: value=int(c.group(1).replace('_',''))
out=subprocess.run(['pina','migrations','status'],capture_output=True,text=True).stdout
quotes=[int(q) for q in re.findall(r'funds ~(\d+) lamports', out)]
need=max(quotes) if quotes else None
print('budget', value, 'needed', need); raise SystemExit(0 if value is not None and need is not None and value >= need else 1)"
